% Base de hechos: Características de aves de Costa Rica
% caracteristicas(NombreComun, Reino, Filo, Color, Peso, Alimento, Habitat, Descripcion).
:- module(aves_cr_caracteristicas, [caracteristicas/8]).
caracteristicas('Nothocercus-Bonapartei', 'Animalia', 'Chordata', 'Marrón con tonalidades rojizas y barras negras', '450-600 gramos', 'Frutas, semillas, insectos y pequeños invertebrados', 'Bosques montanos y nubosos en la región andina', 'El Nothocercus bonapartei es un ave terrestre de tamaño mediano, conocida por su plumaje críptico que le permite camuflarse en el sotobosque. Es una especie tímida y de hábitos nocturnos o crepusculares, que se alimenta principalmente en el suelo.').
caracteristicas('Tinamus-Major', 'Animalia', 'Chordata', 'Marrón con manchas y tonos terrosos', '1.5 - 2.5 kg', 'Insectos, semillas, frutos y pequeños invertebrados', 'Bosques tropicales y subtropicales de América Central y del Sur', 'El Tinamus major es un ave terrestre de tamaño mediano perteneciente a la familia Tinamidae, conocida por su plumaje críptico que le permite camuflarse en el suelo del bosque. Es un ave tímida y principalmente nocturna o crepuscular.').
caracteristicas('Crypturellus-Soui', 'Animalia', 'Chordata', 'Marrón con tonos rojizos y grisáceos', '150-200 gramos', 'Insectos, semillas y pequeños frutos', 'Bosques húmedos tropicales y subtropicales', 'El Crypturellus soui, conocido comúnmente como tinamú de pico corto, es un ave terrestre pequeña que habita en el sotobosque de bosques tropicales. Se caracteriza por su cuerpo compacto, plumaje críptico y hábitos principalmente terrestres y crepusculares.').
caracteristicas('Crypturellus-Boucardi', 'Animalia', 'Chordata', 'Marrón con tonos rojizos y manchas blancas', 'Alrededor de 300-400 gramos', 'Frutas, semillas, insectos y pequeños invertebrados', 'Bosques húmedos tropicales de América Central', 'El Crypturellus boucardi es un ave terrestre pequeña de la familia Tinamidae, conocida por su plumaje críptico que le permite camuflarse en el suelo del bosque. Es principalmente terrestre y se alimenta buscando entre la hojarasca.').
caracteristicas('Crypturellus-Cinnamomeus', 'Animalia', 'Chordata', 'Castaño rojizo con tonos grisáceos', '250-350 gramos', 'Frutas, semillas, insectos y pequeños invertebrados', 'Bosques secos, matorrales y áreas abiertas con vegetación densa', 'El Crypturellus cinnamomeus, conocido comúnmente como tinamú canelo, es un ave terrestre de tamaño pequeño a mediano, con plumaje castaño rojizo que le permite camuflarse en su hábitat natural. Es una especie principalmente terrestre que se alimenta de una dieta variada y habita en regiones de América Central.').
caracteristicas('Dendrocygna-Viduata', 'Animalia', 'Chordata', 'Marrón con manchas negras y blancas', '700-900 gramos', 'Plantas acuáticas, semillas, pequeños invertebrados', 'Zonas húmedas, lagunas, pantanos y ríos de América Central y del Sur', 'El Dendrocygna viduata, conocido como ganso dorsiblanco, es un ave acuática de tamaño mediano con plumaje moteado que habita zonas húmedas y se alimenta principalmente de materia vegetal y pequeños invertebrados.').
caracteristicas('Dendrocygna-Autumnalis', 'Animalia', 'Chordata', 'marrón rojizo con tonos grisáceos y manchas blancas', '0.9 - 1.2 kg', 'plantas acuáticas, semillas, insectos y pequeños invertebrados', 'humedales, lagunas, ríos y estanques de América Central y del Sur', 'El Dendrocygna autumnalis, conocido como ganso o pato silbón, es un ave acuática que se distingue por su característico silbido y su plumaje marrón rojizo. Es una especie migratoria que habita principalmente en zonas húmedas donde encuentra alimento y refugio.').
caracteristicas('Dendrocygna-Bicolor', 'Animalia', 'Chordata', 'Marrón, blanco y negro', '1.2 a 1.5 kg', 'Plantas acuáticas, semillas, pequeños invertebrados', 'Humedales, lagunas, ríos y zonas pantanosas', 'El Dendrocygna bicolor, conocido como pato zambullidor bicolor, es un ave acuática de tamaño medio caracterizada por su plumaje marrón con marcas blancas y negras, adaptada a vivir en zonas húmedas donde se alimenta principalmente de vegetación acuática y pequeños organismos.').
caracteristicas('Anser-Albifrons', 'Animalia', 'Chordata', 'gris con tonos blancos y negros', '2.5 a 3.7 kg', 'plantas acuáticas, semillas, raíces y vegetación', 'humedales, lagos, ríos y praderas cercanas al agua', 'El Anser albifrons, conocido como ganso de frente blanca, es un ave migratoria de tamaño mediano con un característico parche blanco en la frente. Habita en zonas húmedas y se alimenta principalmente de materia vegetal.').
caracteristicas('Sarkidiornis-Sylvicola', 'Animalia', 'Chordata', 'Blanco con manchas negras y azul metálico en el pico', '1.3 - 2.0 kg', 'Plantas acuáticas, semillas, insectos y pequeños invertebrados', 'Zonas húmedas, lagunas, ríos y pantanos en regiones tropicales de América del Sur', 'El Sarkidiornis sylvicola es un pato grande conocido por su pico distintivo y su plumaje blanco con manchas negras, adaptado a ambientes acuáticos donde se alimenta principalmente de plantas y pequeños animales.').
caracteristicas('Cairina-Moschata', 'Animalia', 'Chordata', 'Marrón, negro y blanco', '3 a 6 kg', 'Omnívoro (plantas, insectos, pequeños invertebrados)', 'Zonas húmedas, ríos y lagos en América', 'El Cairina moschata, conocido como pato muscovy, es un ave acuática originaria de América, caracterizada por su tamaño grande, plumaje variado y una carúncula roja distintiva en la cara.').
caracteristicas('Spatula-Discors', 'Animalia', 'Chordata', 'Marrón, blanco y negro con reflejos iridiscentes', '400-700 gramos', 'Plantas acuáticas, semillas, insectos y pequeños invertebrados', 'Humedales, lagos, estanques y ríos con vegetación abundante', 'El Spatula discors, conocido comúnmente como pato cuchara chico, es una especie de pato migratorio caracterizado por su pico ancho y aplanado que utiliza para filtrar alimento del agua. Presenta un plumaje moteado y es conocido por sus patrones de vuelo en grandes bandadas.').
caracteristicas('Spatula-Cyanoptera', 'Animalia', 'Chordata', 'Verde azulado con tonos marrones', '600-900 gramos', 'Plantas acuáticas, insectos y pequeños invertebrados', 'Zonas húmedas, lagunas y estanques de agua dulce', 'El Spatula-Cyanoptera es un pato de tamaño mediano conocido por sus alas de color azul vibrante y su habilidad para nadar y bucear en aguas poco profundas.').
caracteristicas('Spatula-Clypeata', 'Animalia', 'Chordata', 'Marrón, blanco y negro con reflejos iridiscentes', '500-1000 gramos', 'Plantas acuáticas, semillas, insectos y pequeños invertebrados', 'Humedales, lagos, ríos y estuarios', 'El Spatula clypeata, conocido comúnmente como ánade cuchara o pato cuchara, es una especie de pato caracterizada por su pico ancho y aplanado que utiliza para filtrar alimento del agua.').
caracteristicas('Mareca-Americana', 'Animalia', 'Chordata', 'Verde, marrón, blanco y negro', '0.7 a 1.6 kg', 'Plantas acuáticas, semillas, insectos', 'Lagos, ríos, humedales y zonas costeras', 'La Mareca-Americana, también conocida como pato de cabeza verde, es un ave acuática muy común en América del Norte. Presenta un característico plumaje con cabeza verde iridiscente en el macho y un cuerpo marrón moteado en la hembra. Es una especie migratoria que se alimenta principalmente de plantas acuáticas y pequeños invertebrados.').
caracteristicas('Anas-Platyrhynchos', 'Animalia', 'Chordata', 'Macho: cabeza verde iridiscente, cuerpo gris y pecho marrón; Hembra: tonos marrones y beige', '0.9 - 1.3 kg', 'Omnívoro (plantas acuáticas, insectos, pequeños peces)', 'Zonas húmedas, lagos, ríos y estanques', 'El ánade real es un pato común en muchas regiones, conocido por su adaptabilidad a diversos ambientes acuáticos y su característico dimorfismo sexual en el plumaje.').
caracteristicas('Anas-Bahamensis', 'Animalia', 'Chordata', 'Marrón con patrones moteados y tonos blancos en el pecho', '300-500 gramos', 'Plantas acuáticas, semillas, insectos y pequeños invertebrados', 'Zonas húmedas costeras, lagunas salobres y manglares en las Bahamas', 'El ánade bahameño es un pato pequeño y discreto que habita en áreas costeras y humedales de las Bahamas. Se caracteriza por su plumaje moteado marrón y blanco, adaptado para camuflarse en su entorno. Es una especie que se alimenta principalmente de vegetación acuática y pequeños invertebrados.').
caracteristicas('Anas-Acuta', 'Animalia', 'Chordata', 'Marrón claro con negro y blanco', '0.8 a 1.5 kg', 'Plantas acuáticas, semillas, pequeños invertebrados', 'Zonas húmedas, lagunas, ríos y estanques', 'El ánade silbón (Anas acuta) es un pato migratorio conocido por su cola larga y puntiaguda, cuerpo esbelto y plumaje moteado que le permite camuflarse en ambientes acuáticos.').
caracteristicas('Anas-Crecca', 'Animalia', 'Chordata', 'Marrón con tonos verdes y grises', '400-550 gramos', 'Insectos, plantas acuáticas, semillas', 'Zonas húmedas, lagos, ríos y humedales', 'El Anas crecca, conocido como ánade real común o cerceta común, es un pato pequeño y migratorio caracterizado por su plumaje marrón con detalles verdes y grises, que habita principalmente en zonas húmedas y se alimenta de una dieta variada que incluye insectos y plantas acuáticas.').
caracteristicas('Aythya-Valisineria', 'Animalia', 'Chordata', 'Varía, generalmente tonos marrones y blancos', 'Entre 800 y 1200 gramos', 'Vegetación acuática, semillas, pequeños invertebrados', 'Zonas húmedas, lagos y pantanos con vegetación acuática', 'El Aythya valisineria es un pato buceador conocido por habitar en cuerpos de agua dulce con abundante vegetación acuática, donde se alimenta principalmente de plantas y pequeños organismos. Presenta un plumaje que varía en tonos marrones y blancos, adaptado a su entorno acuático.').
caracteristicas('Aythya-Americana', 'Animalia', 'Chordata', 'Negro, blanco y marrón', '900-1500 gramos', 'Moluscos, insectos acuáticos, semillas y plantas acuáticas', 'Lagos, estanques y humedales de América del Norte', 'El Aythya americana, conocido comúnmente como pato americano o pochard americano, es un pato buceador de tamaño mediano con plumaje distintivo negro y blanco. Habita cuerpos de agua dulce donde se alimenta principalmente de moluscos y plantas acuáticas.').
caracteristicas('Aythya-Ferina', 'Animalia', 'Chordata', 'macho: cabeza y cuello rojizos, cuerpo gris y negro; hembra: marrón y gris', '900-1200 gramos', 'plantas acuáticas, semillas, invertebrados', 'lagos, estanques, ríos y humedales de agua dulce', 'El ánade friso es un pato buceador común en Europa y Asia, reconocido por su plumaje distintivo y su habilidad para sumergirse en busca de alimento.').
caracteristicas('Aythya-Collaris', 'Animalia', 'Chordata', 'Negro, blanco y marrón', '700-900 gramos', 'Plant material, semillas acuáticas, invertebrados', 'Lagos, estanques y humedales de América del Norte', 'El Aythya collaris, conocido como pato collarín, es un ave acuática que presenta un collar blanco distintivo en el cuello. Es un buen nadador y buceador, y se alimenta principalmente de vegetación acuática y pequeños invertebrados.').
caracteristicas('Aythya-Marila', 'Animalia', 'Chordata', 'Negro, blanco y marrón', '900-1600 gramos', 'Plantas acuáticas, semillas, invertebrados', 'Lagos, lagunas y zonas costeras de agua dulce y salobre', 'El Aythya marila, conocido como pato zambullidor o pato marila, es un ave acuática que se caracteriza por su plumaje contrastante y su habilidad para sumergirse en busca de alimento.').
caracteristicas('Aythya-Affinis', 'Animalia', 'Chordata', 'Negro, blanco y marrón', '600-900 gramos', 'Plantas acuáticas, semillas, invertebrados', 'Lagos, estanques y humedales de América del Norte', 'El Aythya-affinis, conocido como pato ojinegro, es una especie de pato buceador de tamaño mediano que se caracteriza por su plumaje contrastante y su habilidad para sumergirse en busca de alimento.').
caracteristicas('Lophodytes-Cucullatus', 'Animalia', 'Chordata', 'Negro, blanco y marrón', '500-700 gramos', 'Invertebrados acuáticos, insectos, crustáceos', 'Lagos, estanques, ríos y humedales de América del Norte', 'El Lophodytes cucullatus, conocido como pato capuchino, es un ave acuática pequeña con un patrón distintivo de plumaje en negro y blanco, caracterizada por un penacho en la cabeza. Es un buceador experto que se alimenta de invertebrados acuáticos.').
caracteristicas('Mergus-Serrator', 'Animalia', 'Chordata', 'Negro, blanco y naranja', '1.2 a 1.7 kg', 'Peces y pequeños invertebrados acuáticos', 'Zonas costeras y ríos de agua dulce en regiones templadas y frías', 'El Mergus serrator es un ave acuática conocida como el serreta o pato cuchara, caracterizada por su pico estrecho y dentado que le ayuda a capturar peces. Presenta plumaje mayormente negro y blanco, con detalles naranjas en el pico y patas, y es un excelente nadador y buceador.').
caracteristicas('Nomonyx-Dominicus', 'Animalia', 'Chordata', 'Desconocido', 'Desconocido', 'Desconocido', 'Desconocido', 'El Nomonyx-Dominicus es una especie de ave ficticia sin datos científicos disponibles.').
caracteristicas('Oxyura-Jamaicensis', 'Animalia', 'Chordata', 'Azul brillante en el macho, marrón y gris en la hembra', '1.2 a 1.5 kg', 'Invertebrados acuáticos, semillas y plantas acuáticas', 'Lagos, estanques y humedales de agua dulce', 'El Oxyura jamaicensis, conocido como pato de pico azul, es un ave acuática destacada por su pico ancho y azul brillante en los machos durante la temporada de apareamiento. Es un excelente buceador que se alimenta principalmente en el fondo de cuerpos de agua dulce.').
caracteristicas('Ortalis-Vetula', 'Animalia', 'Chordata', 'Marrón grisáceo con tonos iridiscentes', '300-400 gramos', 'Frutas, semillas, insectos', 'Bosques tropicales y subtropicales', 'El Ortalis vetula, conocido comúnmente como pava de monte o chachalaca parda, es un ave galliforme de tamaño mediano que habita principalmente en regiones boscosas del sureste de México y América Central. Se caracteriza por su plumaje marrón con reflejos iridiscentes y su llamada distintiva.').
caracteristicas('Ortalis-Cinereiceps', 'Animalia', 'Chordata', 'grisáceo con tonos marrones', 'aproximadamente 300-400 gramos', 'frutas, semillas e insectos', 'bosques tropicales y subtropicales de América Central', 'Ave terrestre de tamaño mediano, con plumaje principalmente gris, cabeza ligeramente más clara, y hábitos omnívoros. Es reconocida por su llamada característica y su comportamiento tímido.').
caracteristicas('Penelope-Purpurascens', 'Animalia', 'Chordata', 'Marrón oscuro con tonos purpúreos y manchas blancas', '1.2 a 1.5 kg', 'Frutas, semillas, hojas y pequeños invertebrados', 'Bosques tropicales y subtropicales húmedos de América Central y del Sur', 'El Penelope purpurascens es un ave de tamaño mediano perteneciente a la familia Cracidae. Se caracteriza por su plumaje marrón oscuro con reflejos purpúreos y manchas blancas en las alas. Habita principalmente en bosques húmedos donde se alimenta de frutos y otros materiales vegetales, contribuyendo a la dispersión de semillas.').
caracteristicas('Chamaepetes-Unicolor', 'Animalia', 'Chordata', 'Verde oliva', '150-200 gramos', 'Frutas, insectos y pequeños invertebrados', 'Bosques húmedos montanos de América Central', 'Ave de tamaño mediano con plumaje predominantemente verde oliva, conocida por su comportamiento tranquilo y su dieta omnívora que incluye frutas e insectos.').
caracteristicas('Crax-Rubra', 'Animalia', 'Chordata', 'Negro con rojo brillante en la cabeza', '1.5 - 2 kg', 'Frutas, semillas, insectos y pequeños vertebrados', 'Bosques tropicales y subtropicales de América Central y del Sur', 'El Crax rubra, conocido como pavo o guacharaca roja, es un ave grande y vistosa con plumaje negro brillante y una cabeza roja desnuda. Es conocido por su canto fuerte y su papel importante en la dispersión de semillas en su ecosistema.').
caracteristicas('Rhynchortyx-Cinctus', 'Animalia', 'Chordata', 'Marrón rojizo con manchas negras y blancas', 'aproximadamente 300-400 gramos', 'Insectos, semillas y pequeños invertebrados', 'Bosques tropicales y subtropicales de América Central', 'Ave terrestre de tamaño mediano, conocida por su plumaje moteado y su comportamiento tímido, que se alimenta principalmente en el suelo del bosque.').
caracteristicas('Dendrortyx-Leucophrys', 'Animalia', 'Chordata', 'Marrón con patrones moteados y tonos blancos y negros', 'aproximadamente 400-600 gramos', 'Insectos, semillas y frutos', 'Bosques húmedos y zonas montañosas de América Central', 'El Dendrortyx leucophrys es un ave galliforme de tamaño mediano, conocida por su patrón moteado que le proporciona camuflaje en el sotobosque. Se alimenta principalmente en el suelo y es conocido por su comportamiento sigiloso y su canto característico.').
caracteristicas('Colinus-Leucopogon', 'Animalia', 'Chordata', 'Marrón con manchas blancas y negras', '150 gramos', 'Semillas, insectos y pequeños invertebrados', 'Zonas arbustivas y praderas abiertas', 'El Colinus leucopogon es un ave terrestre conocida por su plumaje moteado que le proporciona camuflaje en su entorno natural. Es un ave de tamaño pequeño a mediano que se alimenta principalmente en el suelo.').
caracteristicas('Colinus-Cristatus', 'Animalia', 'Chordata', 'Marrón con rayas negras y blancas en la cabeza', '150-200 gramos', 'Semillas, insectos y pequeños invertebrados', 'Zonas abiertas, pastizales y áreas agrícolas', 'El Colinus cristatus, conocido comúnmente como codorniz crestada, es un ave pequeña y terrestre que destaca por su cresta distintiva formada por plumas erectas en la cabeza. Es un ave sociable que se alimenta principalmente en el suelo y tiene un canto característico.').
caracteristicas('Odontophorus-Gujanensis', 'Animalia', 'Chordata', 'Marrón con patrones moteados y barras en tonos rojizos y negros', '150-200 gramos', 'Semillas, insectos y pequeños invertebrados', 'Bosques tropicales y subtropicales de América Central y del Sur', 'El Odontophorus gujanensis, conocido comúnmente como codorniz manchada, es un ave terrestre que se caracteriza por su plumaje camuflado, adaptado para vivir en el sotobosque. Es un ave tímida y solitaria que se alimenta principalmente en el suelo.').
caracteristicas('Odontophorus-Melanotis', 'Animalia', 'Chordata', 'Marrón oscuro con manchas negras y tonos rojizos', 'aproximadamente 200-300 gramos', 'Semillas, frutos, insectos y pequeños invertebrados', 'Bosques húmedos y selvas subtropicales de América Central', 'El Odontophorus melanotis es un ave terrestre de la familia Odontophoridae, conocida por su plumaje críptico que le permite camuflarse en el suelo del bosque. Es principalmente terrestre y se alimenta buscando en el sustrato forestal.').
caracteristicas('Odontophorus-Leucolaemus', 'Animalia', 'Chordata', 'Marrón con manchas blancas y negras', '200-300 gramos', 'Frutos, semillas e insectos', 'Bosques tropicales y subtropicales de América Central', 'El Odontophorus leucolaemus es un ave terrestre perteneciente a la familia Odontophoridae, conocida por su plumaje moteado que le proporciona camuflaje en el suelo del bosque. Es una especie reservada y difícil de observar, que se alimenta principalmente de frutos y pequeños invertebrados.').
caracteristicas('Odontophorus-Guttatus', 'Animalia', 'Chordata', 'Moteado marrón, negro y blanco', 'aproximadamente 200-300 gramos', 'Insectos, semillas y pequeños frutos', 'Bosques tropicales y subtropicales húmedos de América Central', 'El Odontophorus guttatus es una especie de ave de la familia Odontophoridae, conocida por su plumaje moteado que le proporciona un excelente camuflaje en el suelo del bosque. Es un ave terrestre que se alimenta principalmente de insectos y semillas, y es característico por su canto distintivo.').
caracteristicas('Columba-Livia', 'Animalia', 'Chordata', 'gris con tonos iridiscentes en el cuello', '250-380 gramos', 'semillas, frutas, restos de comida', 'zonas urbanas, parques, áreas rurales', 'La Columba livia, comúnmente conocida como paloma bravía o paloma común, es una especie de ave ampliamente distribuida en todo el mundo, conocida por su adaptabilidad a ambientes urbanos y su plumaje predominantemente gris con reflejos verdes y púrpuras en el cuello.').
caracteristicas('Patagioenas-Cayennensis', 'Animalia', 'Chordata', 'gris con tonos azulados y pecho rosado', 'aproximadamente 250-300 gramos', 'frutas, semillas y pequeños invertebrados', 'bosques tropicales y áreas abiertas de América Central y del Sur', 'La Patagioenas cayennensis es una paloma de tamaño mediano reconocida por su plumaje gris azulado y pecho rosado, común en regiones tropicales donde se alimenta principalmente de frutas y semillas.').
caracteristicas('Patagioenas-Speciosa', 'Animalia', 'Chordata', 'gris con tonos rosados y verdes metálicos', '200-300 gramos', 'frutas, semillas e insectos', 'bosques tropicales y subtropicales', 'La Patagioenas speciosa es una paloma de tamaño mediano caracterizada por su plumaje principalmente gris con reflejos rosados y verdes. Habita en áreas boscosas y se alimenta principalmente de frutas y semillas.').
caracteristicas('Patagioenas-Leucocephala', 'Animalia', 'Chordata', 'gris con cabeza blanca', '150-200 gramos', 'frutas, semillas, insectos', 'bosques tropicales y subtropicales', 'La Patagioenas leucocephala es una especie de paloma que se distingue por su cabeza blanca y plumaje gris, común en regiones tropicales donde se alimenta principalmente de frutas y semillas.').
caracteristicas('Patagioenas-Flavirostris', 'Animalia', 'Chordata', 'Gris con tonos marrones y amarillo en el pico', '200-250 gramos', 'Frutas, semillas y ocasionalmente insectos', 'Bosques y áreas montañosas de América Central y América del Sur', 'La Patagioenas flavirostris es una paloma de tamaño mediano, reconocida por su pico amarillo y plumaje mayormente gris con matices marrones, que habita en zonas boscosas y montañosas. Se alimenta principalmente de frutas y semillas, contribuyendo a la dispersión de semillas en su ecosistema.').
caracteristicas('Patagioenas-Fasciata', 'Animalia', 'Chordata', 'gris con bandas negras y blancas en el cuello', 'aproximadamente 250 gramos', 'frutas, semillas y pequeños insectos', 'bosques, áreas urbanas y rurales en América del Norte y Central', 'La Patagioenas fasciata es una paloma de tamaño mediano conocida por sus bandas distintivas en el cuello y su capacidad para adaptarse a diversos hábitats.').
caracteristicas('Patagioenas-Subvinacea', 'Animalia', 'Chordata', 'Gris azulado con tonos pardos y rosados', '120-150 gramos', 'Frutas, semillas y pequeños invertebrados', 'Bosques húmedos y áreas montañosas de América del Sur', 'La Patagioenas subvinacea es una paloma mediana que se caracteriza por su plumaje gris azulado con matices rosados en el pecho. Habita principalmente en zonas montañosas y boscosas, y se alimenta principalmente de frutas y semillas. Es conocida por su vuelo rápido y su canto distintivo.').
caracteristicas('Patagioenas-Nigrirostris', 'Animalia', 'Chordata', 'gris oscuro con tonos azulados y negro en el pico', 'aproximadamente 200-250 gramos', 'frutas, semillas y ocasionalmente insectos', 'bosques húmedos y áreas montañosas de América Central', 'La Patagioenas nigrirostris es una paloma de tamaño mediano, reconocida por su pico negro y plumaje gris oscuro con reflejos azulados. Habita en regiones montañosas y boscosas, donde se alimenta principalmente de frutas y semillas.').
caracteristicas('Streptopelia-Decaocto', 'Animalia', 'Chordata', 'Marrón claro con manchas negras en el cuello', '110-140 gramos', 'Semillas, frutos, insectos', 'Zonas urbanas, parques, campos abiertos', 'La tórtola turca es una paloma de tamaño mediano conocida por su canto característico y su adaptabilidad a entornos urbanos y rurales.').
caracteristicas('Columbina-Inca', 'Animalia', 'Chordata', 'Marrón grisáceo con manchas blancas', '30-40 gramos', 'Semillas, insectos pequeños', 'Zonas abiertas, campos y áreas semiáridas de América del Sur', 'La Columbina-Inca es una pequeña paloma terrestre conocida por su plumaje moteado y su comportamiento tímido. Se encuentra principalmente en regiones abiertas donde se alimenta en el suelo.').
caracteristicas('Columbina-Passerina', 'Animalia', 'Chordata', 'Marrón grisáceo con manchas blancas y negras', '30-50 gramos', 'Semillas, insectos y pequeños invertebrados', 'Áreas abiertas, campos, bordes de bosques y zonas semiáridas', 'Pequeña paloma terrestre conocida por sus patrones de plumaje moteado y su comportamiento terrestre al buscar alimento.').
caracteristicas('Columbina-Minuta', 'Animalia', 'Chordata', 'Marrón grisáceo con tonos rosados y manchas negras', '20-30 gramos', 'Semillas, pequeños insectos y frutos', 'Áreas abiertas, campos, bordes de bosques y zonas urbanas', 'La Columbina minutia es una pequeña paloma con un tamaño compacto, caracterizada por su plumaje moteado y su comportamiento tranquilo. Es común en América Central y del Sur, donde se adapta bien a distintos ambientes.').
caracteristicas('Columbina-Talpacoti', 'Animalia', 'Chordata', 'gris, con tonos marrones y manchas negras', '30-40 gramos', 'semillas, pequeños insectos y frutos', 'áreas abiertas, jardines, campos y bordes de bosques', 'Pequeña paloma de cuerpo compacto, común en América Central y del Sur, conocida por su canto suave y su capacidad de adaptarse a diversos ambientes.').
caracteristicas('Claravis-Pretiosa', 'Animalia', 'Chordata', 'Azul con manchas negras', '100-150 gramos', 'Frutas, semillas e insectos', 'Bosques tropicales y subtropicales', 'Ave mediana conocida por su plumaje azul brillante con manchas negras, habita en regiones boscosas de América Central y del Sur, y se alimenta principalmente de frutas, semillas e insectos.').
caracteristicas('Paraclaravis-Mondetoura', 'Animalia', 'Chordata', 'principalmente azul con tonos grisáceos y detalles en negro', 'aproximadamente 100 gramos', 'frutos, semillas y pequeños invertebrados', 'bosques tropicales húmedos de América del Sur', 'El Paraclaravis mondetoura es una especie de ave perteneciente a la familia Columbidae, caracterizada por su plumaje azul con matices grises, vive en ambientes forestales donde se alimenta principalmente de frutas y semillas.').
caracteristicas('Geotrygon-Montana', 'Animalia', 'Chordata', 'Marrón con tonos grisáceos y rojizos', '150-200 gramos', 'Semillas, frutos, insectos pequeños', 'Bosques tropicales y subtropicales húmedos', 'La Geotrygon montana es una paloma terrestre de tamaño mediano que habita principalmente en el sotobosque de bosques húmedos. Presenta un plumaje principalmente marrón con matices grisáceos y rojizos, y es conocida por su comportamiento reservado y su alimentación basada en semillas y pequeños invertebrados.').
caracteristicas('Geotrygon-Violacea', 'Animalia', 'Chordata', 'gris azulado con manchas blancas y tonos violáceos', 'aproximadamente 150 gramos', 'semillas, frutos y pequeños invertebrados', 'bosques húmedos tropicales y subtropicales', 'La Geotrygon violacea es una paloma terrestre que se caracteriza por su plumaje gris azulado con tonos violáceos y manchas blancas en las alas. Es una especie tímida que habita principalmente en el sotobosque de bosques húmedos, donde se alimenta principalmente en el suelo.').
caracteristicas('Leptotrygon-Veraguensis', 'Animalia', 'Chordata', 'Marrón oscuro con manchas pálidas', 'Alrededor de 2 kg', 'Pequeños invertebrados y peces', 'Ríos y cuerpos de agua dulce en Panamá', 'Leptotrygon veraguensis es una especie de raya de agua dulce, caracterizada por su tamaño pequeño y su capacidad para vivir en ambientes fluviales. Presenta un cuerpo aplanado adaptado para el fondo de ríos y se alimenta principalmente de invertebrados bentónicos.').
caracteristicas('Leptotila-Verreauxi', 'Animalia', 'Chordata', 'Marrón grisáceo con tonos rosados en el pecho', '150-200 gramos', 'Semillas, frutos, insectos', 'Bosques tropicales y subtropicales, áreas abiertas con vegetación', 'La Leptotila verreauxi es una paloma de tamaño mediano que se caracteriza por su plumaje marrón grisáceo y tonos rosados en el pecho. Es una especie que habita principalmente en América Central y partes de América del Sur, alimentándose de semillas, frutos e insectos, y prefiriendo áreas boscosas y semiabiertas.').
caracteristicas('Leptotila-Cassinii', 'Animalia', 'Chordata', 'gris, con tonos marrones y rosados en el pecho', '150-200 gramos', 'semillas, frutos, insectos pequeños', 'bosques húmedos y áreas boscosas de América Central', 'La Leptotila cassinii es una paloma de tamaño mediano caracterizada por su plumaje principalmente gris con tonos marrones y un pecho rosado. Es una especie terrestre que se alimenta principalmente en el suelo y es común en bosques húmedos y áreas boscosas.').
caracteristicas('Leptotila-Plumbeiceps', 'Animalia', 'Chordata', 'Gris plomizo con tonos rosados y marrones', '150-200 gramos', 'Frutas, semillas e insectos', 'Bosques húmedos y áreas arboladas de América Central y del Norte de América del Sur', 'La Leptotila plumbeiceps es una paloma de tamaño mediano conocida por su plumaje gris plomizo y su comportamiento tranquilo. Se encuentra principalmente en regiones boscosas y se alimenta principalmente de frutas y pequeños invertebrados.').
caracteristicas('Zentrygon-Costaricensis', 'Animalia', 'Chordata', 'Marrón con tonos grises y rojizos', 'aproximadamente 150 gramos', 'Semillas, frutos y pequeños invertebrados', 'Bosques húmedos montanos de Costa Rica y Panamá', 'Ave terrestre de la familia Columbidae, conocida por su plumaje críptico que le permite camuflarse en el suelo del bosque. Tiene un canto suave y es principalmente solitaria.').
caracteristicas('Zentrygon-Lawrencii', 'Animalia', 'Chordata', 'Marrón con patrones grisáceos y tonos rojizos', 'aproximadamente 200 gramos', 'Frutas, semillas e insectos', 'Bosques húmedos montanos de América Central', 'La Zentrygon lawrencii es una especie de ave de la familia Columbidae, conocida por su plumaje críptico y su comportamiento reservado en el sotobosque de bosques montanos.').
caracteristicas('Zentrygon-Chiriquensis', 'Animalia', 'Chordata', 'Marrón con tonos grisáceos y manchas blancas', '150-200 gramos', 'Frutas, semillas e insectos', 'Bosques montanos húmedos de Chiriquí, Panamá', 'La Zentrygon chiriquensis es una especie de pava o guajolote pequeña, con plumaje principalmente marrón y gris, adaptada a vivir en las áreas boscosas montañosas, donde se alimenta de frutos y pequeños invertebrados.').
caracteristicas('Zenaida-Asiatica', 'Animalia', 'Chordata', 'gris con tonos marrones y blanco', 'aproximadamente 120 gramos', 'semillas, frutos y pequeños invertebrados', 'áreas abiertas, jardines y zonas rurales en el Caribe', 'La Zenaida asiatica, también conocida como paloma zenaida, es una paloma de tamaño mediano con plumaje grisáceo y tonos marrones, común en el Caribe. Se caracteriza por su vuelo rápido y su canto suave, y suele habitar áreas abiertas y jardines donde busca alimento principalmente en el suelo.').
caracteristicas('Zenaida-Auriculata', 'Animalia', 'Chordata', 'grisáceo con tonos marrones y manchas blancas en las alas', '120-140 gramos', 'semillas, frutas, insectos', 'zonas abiertas, campos, áreas urbanas y rurales de América del Sur y Central', 'La Zenaida auriculata es una paloma de tamaño mediano reconocida por su plumaje grisáceo con manchas blancas en las alas y una característica mancha negra detrás del ojo. Es común en ambientes variados y se alimenta principalmente de semillas e insectos.').
caracteristicas('Zenaida-Macroura', 'Animalia', 'Chordata', 'Gris con tonos marrones y manchas blancas', '120-150 gramos', 'Semillas, frutos, insectos', 'Áreas abiertas, campos, parques y jardines', 'La Zenaida macroura, conocida como tórtola cola larga, es una paloma pequeña con una cola larga y puntiaguda, plumaje mayormente grisáceo, y un característico sonido suave y melódico.').
caracteristicas('Crotophaga-Major', 'Animalia', 'Chordata', 'Negro y blanco', '200-300 gramos', 'Insectos, pequeños reptiles y frutas', 'Bosques tropicales y áreas abiertas con árboles', 'El Crotophaga Major, conocido comúnmente como guira, es un ave de tamaño mediano que destaca por su plumaje contrastante en negro y blanco. Es una especie social y ruidosa, que se alimenta principalmente de insectos y pequeños animales, y habita principalmente en regiones tropicales de América.').
caracteristicas('Crotophaga-Ani', 'Animalia', 'Chordata', 'Negro con brillo metálico', '85-110 gramos', 'Insectos, pequeños reptiles y frutas', 'Bosques tropicales y subtropicales, áreas abiertas con arbustos', 'El Crotophaga-Ani es un ave de tamaño mediano conocida por su plumaje negro brillante y su comportamiento social, que incluye la anidación cooperativa. Es común en regiones del Caribe y América Central.').
caracteristicas('Crotophaga-Sulcirostris', 'Animalia', 'Chordata', 'Negro con reflejos azulados y partes blancas', '60-90 gramos', 'Insectos, pequeños invertebrados y frutas', 'Bosques secos, matorrales y áreas abiertas en México y Centroamérica', 'Ave de tamaño mediano conocida por su comportamiento social y su canto característico; posee un pico largo y ligeramente curvado, adaptado para capturar insectos.').
caracteristicas('Tapera-Naevia', 'Animalia', 'Chordata', 'Predominantemente marrón con manchas negras y blancas', 'aproximadamente 50-70 gramos', 'Insectos y otros invertebrados', 'Bosques tropicales y subtropicales, áreas abiertas con vegetación densa', 'El Tapera-Naevia es un ave nocturna conocida por su camuflaje eficaz y su capacidad para imitar sonidos. Posee un plumaje moteado que le ayuda a pasar desapercibido en su entorno natural.').
caracteristicas('Dromococcyx-Phasianellus', 'Animalia', 'Chordata', 'Marrón, blanco y negro con patrones rayados', 'aproximadamente 50 gramos', 'Insectos y otros invertebrados', 'Bosques tropicales y subtropicales de América Central y del Sur', 'El Dromococcyx phasianellus es un ave cuculiforme conocida por su llamativo plumaje con patrones rayados que le proporcionan camuflaje en su hábitat forestal. Posee un canto distintivo y es un parásito de cría, depositando sus huevos en nidos de otras aves.').
caracteristicas('Morococcyx-Erythropygus', 'Animalia', 'Chordata', 'Negro con tonos iridiscentes y rojo en la parte inferior', 'aproximadamente 300 gramos', 'Insectos y pequeños invertebrados', 'Bosques tropicales y subtropicales de América Central', 'El Morococcyx erythropygus es un ave de tamaño mediano conocida por su plumaje negro brillante y su distintiva cola roja. Es un cucúlido que se alimenta principalmente de insectos, y se encuentra habitando áreas boscosas donde puede camuflarse fácilmente.').
caracteristicas('Neomorphus-Geoffroyi', 'Animalia', 'Chordata', 'Marrón con tonos grises y manchas blancas', '700-900 gramos', 'Insectos, pequeños reptiles y frutos', 'Bosques húmedos tropicales de América Central y del Sur', 'El Neomorphus geoffroyi es un ave terrestre de la familia Cuculidae, conocida por su tamaño mediano y su plumaje camuflado que le permite moverse sigilosamente en el suelo del bosque en busca de alimento.').
caracteristicas('Piaya-Cayana', 'Animalia', 'Chordata', 'Marrón grisáceo con tonos rojizos', '120-150 gramos', 'Insectos, pequeños reptiles, frutos', 'Bosques tropicales y subtropicales, áreas abiertas con árboles', 'La Piaya-Cayana es un ave de tamaño mediano conocida por su canto melodioso y su habilidad para moverse ágilmente entre la vegetación. Presenta un plumaje marrón grisáceo con tonos rojizos y una cola larga. Se alimenta principalmente de insectos y pequeños vertebrados, y habita en regiones tropicales de América Central y del Sur.').
caracteristicas('Coccyzus-Melacoryphus', 'Animalia', 'Chordata', 'Marrón con tonos grises y blanco', 'aproximadamente 40-60 gramos', 'Insectos y pequeños invertebrados', 'Bosques, áreas arbustivas y jardines', 'El Coccyzus melacoryphus es un ave de tamaño mediano conocida por su canto distintivo y su plumaje con tonos marrones y grises. Se alimenta principalmente de insectos y habita en áreas boscosas y arbustivas en Sudamérica.').
caracteristicas('Coccyzus-Americanus', 'Animalia', 'Chordata', 'marrón, blanco y negro', '40-70 gramos', 'insectos y pequeños invertebrados', 'bosques, áreas arbustivas y zonas ribereñas en América del Norte y Central', 'Ave conocida como cucarachero americano, de tamaño mediano, con cola larga y distintiva llamada cuculiforme, que se alimenta principalmente de insectos y tiene un canto característico.').
caracteristicas('Coccyzus-Minor', 'Animalia', 'Chordata', 'Marrón claro con tonos grisáceos y blanco en el vientre', '30-50 gramos', 'Insectos, especialmente orugas y escarabajos', 'Bosques subtropicales y tropicales, áreas arbustivas', 'El Coccyzus minor es un ave migratoria pequeña conocida por su plumaje discreto y su canto suave. Se alimenta principalmente de insectos que captura en vuelo o en la vegetación.').
caracteristicas('Coccyzus-Ferrugineus', 'Animalia', 'Chordata', 'Marrón rojizo con franjas blancas y negras', '40-50 gramos', 'Insectos y pequeños invertebrados', 'Bosques tropicales y subtropicales, áreas arbustivas', 'El Coccyzus ferrugineus es un ave de tamaño mediano conocida por su plumaje marrón rojizo y su habilidad para alimentarse principalmente de insectos en hábitats forestales densos.').
caracteristicas('Coccyzus-Erythropthalmus', 'Animalia', 'Chordata', 'Marrón oliva con partes inferiores blancas y ojos rojos', '40-60 gramos', 'Insectos, arañas, pequeños reptiles y frutas', 'Bosques, matorrales y áreas arboladas en América del Norte y Central', 'El Coccyzus erythropthalmus, conocido como cuclillo de ojos rojos, es un ave migratoria que se destaca por sus ojos rojos brillantes y su capacidad para cazar insectos en vuelo y en el follaje.').
caracteristicas('Chordeiles-Acutipennis', 'Animalia', 'Chordata', 'Marrón grisáceo con manchas y franjas blancas', '50-70 gramos', 'Insectos voladores', 'Áreas abiertas, bosques secos y semiáridos', 'Ave nocturna de la familia Caprimulgidae, conocida por su camuflaje y su vuelo silencioso. Se alimenta principalmente de insectos durante el crepúsculo y la noche.').
caracteristicas('Chordeiles-Minor', 'Animalia', 'Chordata', 'Marrón, gris y blanco con patrones moteados', '40-60 gramos', 'Insectos voladores', 'Áreas abiertas como campos, sabanas y bordes de bosques en América', 'El Chordeiles minor, conocido como chotacabras menor, es un ave nocturna que se alimenta principalmente de insectos en vuelo. Tiene un plumaje críptico que le permite camuflarse en el suelo durante el día.').
caracteristicas('Lurocalis-Semitorquatus', 'Animalia', 'Chordata', 'Marrón oscuro con tonos oliva y manchas blancas en el pecho', '40-60 gramos', 'Insectos y otros artrópodos', 'Bosques tropicales y subtropicales, principalmente en áreas húmedas y sombreadas', 'El Lurocalis semitorquatus es un ave nocturna de tamaño mediano perteneciente a la familia Caprimulgidae. Se caracteriza por su plumaje críptico que le permite camuflarse en el entorno forestal. Su actividad principal es durante el crepúsculo y la noche, donde se alimenta principalmente de insectos.').
caracteristicas('Nyctidromus-Albicollis', 'Animalia', 'Chordata', 'Marrón con manchas y tonos beige', 'aproximadamente 60-90 gramos', 'Insectos y pequeños invertebrados', 'Bosques, matorrales y áreas abiertas de América Central y del Sur', 'El Nyctidromus albicollis, conocido como chotacabras o chotacabra común, es un ave nocturna caracterizada por su plumaje críptico que le permite camuflarse en el suelo. Es un cazador activo durante la noche, alimentándose principalmente de insectos.').
caracteristicas('Hydropsalis-Cayennensis', 'Animalia', 'Chordata', 'Marrón oscuro con manchas claras', '30-40 gramos', 'Insectos y pequeños invertebrados', 'Bosques tropicales y áreas abiertas con vegetación', 'Ave nocturna de tamaño pequeño a mediano, conocida por su vuelo silencioso y su capacidad para cazar insectos en la oscuridad.').
caracteristicas('Nyctiphrynus-Ocellatus', 'Animalia', 'Chordata', 'Marrón con patrones moteados y ocelos en las alas', '30-40 gramos', 'Insectos y otros invertebrados', 'Bosques tropicales y subtropicales de América Central', 'Ave nocturna de tamaño pequeño a mediano, conocida por sus patrones de camuflaje y hábitos insectívoros durante la noche.').
caracteristicas('Antrostomus-Carolinensis', 'Animalia', 'Chordata', 'Marrón con patrones moteados y rayas blancas', '40-60 gramos', 'Insectos y otros invertebrados', 'Bosques deciduos y mixtos en América del Norte', 'El Antrostomus carolinensis, conocido como chotacabras de Carolina, es un ave nocturna que se camufla perfectamente con su entorno gracias a su plumaje moteado. Se alimenta principalmente de insectos voladores y es conocido por su canto distintivo durante las noches de verano.').
caracteristicas('Antrostomus-Rufus', 'Animalia', 'Chordata', 'Marrón rojizo con patrones moteados', '30-40 gramos', 'Insectos nocturnos', 'Bosques densos y áreas boscosas de América Central y del Sur', 'El Antrostomus rufus es un ave nocturna conocida por su plumaje críptico que le permite camuflarse en la corteza de los árboles. Se alimenta principalmente de insectos y tiene un canto característico durante la noche.').
caracteristicas('Antrostomus-Ridgwayi', 'Animalia', 'Chordata', 'Marrón con patrones moteados y rayas', '30-40 gramos', 'Insectos nocturnos', 'Bosques secos y matorrales en el suroeste de Estados Unidos y noroeste de México', 'Ave nocturna de tamaño mediano, conocida como autillo de Ridgway, con un canto distintivo y hábitos crepusculares y nocturnos.').
caracteristicas('Antrostomus-Vociferus', 'Animalia', 'Chordata', 'Marrón con patrones moteados y tonos rojizos', '30-50 gramos', 'Insectos y pequeños invertebrados', 'Bosques y áreas boscosas de América del Norte', 'El Antrostomus vociferus, conocido comúnmente como el chotacabras vociferante, es un ave nocturna que se destaca por su característico canto fuerte y repetitivo. Posee un plumaje críptico que le permite camuflarse eficazmente entre las hojas y la corteza de los árboles.').
caracteristicas('Antrostomus-Saturatus', 'Animalia', 'Chordata', 'Marrón con patrones moteados', '30-50 gramos', 'Insectos nocturnos', 'Bosques montañosos y selvas tropicales de América Central', 'Ave nocturna de tamaño mediano perteneciente a la familia Caprimulgidae, conocida por su camuflaje y hábitos crepusculares y nocturnos.').
