caracteristicas('Colaptes-Rubiginosus', 'Animalia', 'Chordata', 'Marrón rojizo con manchas negras', 'aproximadamente 90-120 gramos', 'Insectos, larvas, pequeños invertebrados', 'Bosques secos y áreas abiertas con árboles en América del Sur', 'El Colaptes rubiginosus es un pájaro carpintero de tamaño medio, conocido por su plumaje marrón rojizo y hábitos excavadores para buscar alimento.').
caracteristicas('Herpetotheres-Cachinnans', 'Animalia', 'Chordata', 'Verde oliva con tonos amarillentos y blanco en el vientre', '45-60 gramos', 'Insectos y pequeños invertebrados', 'Bosques tropicales y subtropicales, bordes de selva y áreas abiertas con árboles', 'El Herpetotheres cachinnans, conocido como el martín pescador bufo, es un ave de tamaño mediano con plumaje predominantemente verde oliva, caracterizada por su comportamiento activo y su dieta insectívora. Habita principalmente en regiones de América Central y del Sur.').
caracteristicas('Micrastur-Semitorquatus', 'Animalia', 'Chordata', 'Marrón oscuro con partes inferiores más claras y manchas blancas en la cola', '150-250 gramos', 'Pequeños mamíferos, aves, reptiles e insectos', 'Bosques tropicales y subtropicales de América Central y del Sur', 'El Micrastur semitorquatus es un ave rapaz nocturna conocida como gavilán azor o azor semitorcido, caracterizada por su plumaje oscuro y hábitos de caza sigilosos en áreas boscosas.').
caracteristicas('Micrastur-Mirandollei', 'Animalia', 'Chordata', 'principalmente gris oscuro con partes inferiores más claras y cola con bandas', 'aproximadamente 150-200 gramos', 'pequeños vertebrados como reptiles, aves y mamíferos, además de insectos', 'bosques tropicales y subtropicales de América del Sur', 'El Micrastur mirandollei es un halcón pequeño y sigiloso, conocido por su habilidad para cazar en áreas densas y su plumaje que le permite camuflarse en el entorno forestal.').
caracteristicas('Micrastur-Ruficollis', 'Animalia', 'Chordata', 'Marrón rojizo con partes inferiores más claras y patrones oscuros en las alas', 'aproximadamente 150-250 gramos', 'Pequeños mamíferos, aves, reptiles e insectos', 'Bosques tropicales y subtropicales de América Central y del Sur', 'Ave rapaz de tamaño mediano, conocida por su cuello rojizo y su habilidad para cazar en ambientes densos y sombríos.').
caracteristicas('Caracara-Plancus', 'Animalia', 'Chordata', 'Negro, blanco y marrón con detalles amarillos en la cara', '1.2 a 1.6 kg', 'Carroña, insectos, pequeños vertebrados y huevos', 'Zonas abiertas, sabanas, áreas agrícolas y bosques abiertos en América del Sur', 'El Caracara-Plancus es un ave rapaz diurna conocida por su inteligencia y adaptabilidad. Tiene un cuerpo robusto, cabeza desnuda amarilla y plumaje en tonos contrastantes. Se alimenta principalmente de carroña, pero también caza pequeños animales y consume insectos.').
caracteristicas('Ibycter-Americanus', 'Animalia', 'Chordata', 'Negro con pico rojo brillante', 'aproximadamente 300 gramos', 'Frutas, insectos y pequeños invertebrados', 'Bosques tropicales de América Central y del Sur', 'El Ibycter-Americanus es un ave tropical conocida por su llamativo pico rojo y su plumaje negro. Se encuentra principalmente en regiones boscosas, donde se alimenta de frutas y pequeños insectos, contribuyendo a la dispersión de semillas en su ecosistema.').
caracteristicas('Daptrius-Chimachima', 'Animalia', 'Chordata', 'Negro y blanco con patrones distintivos', 'Alrededor de 130 gramos', 'Insectos y pequeños invertebrados', 'Bosques tropicales y subtropicales de América del Sur', 'El Daptrius chimachima es un ave paseriforme conocida por su plumaje contrastante y su habilidad para cazar insectos en vuelo. Es común en áreas boscosas húmedas y juega un papel importante en el control de insectos.').
caracteristicas('Falco-Sparverius', 'Animalia', 'Chordata', 'Naranja rojizo con barras negras, blanco en el vientre', '120-165 gramos', 'Insectos, pequeños mamíferos y aves', 'Áreas abiertas, campos, bordes de bosques y zonas urbanas', 'El Falco sparverius, conocido como cernícalo americano, es un pequeño halcón reconocido por su tamaño compacto y su habilidad para mantenerse suspendido en el aire mientras caza. Presenta un plumaje distintivo con tonos anaranjados y barras negras, y es común en América desde Canadá hasta Tierra del Fuego.').
caracteristicas('Falco-Columbarius', 'Animalia', 'Chordata', 'Marrón grisáceo con manchas blancas y negras', '100-200 gramos', 'Pequeñas aves, insectos y pequeños mamíferos', 'Zonas abiertas, tundra, áreas costeras y bosques boreales', 'El halcón es un ave pequeña y rápida, conocida por su habilidad para cazar en vuelo. Presenta un plumaje moteado que le permite camuflarse en su entorno, y es uno de los halcones más pequeños de su género.').
caracteristicas('Falco-Femoralis', 'Animalia', 'Chordata', 'Marrón oscuro con tonos grisáceos', '300-400 gramos', 'Pequeñas aves, insectos y pequeños mamíferos', 'Bosques y áreas montañosas de América Central y del Sur', 'El Falco femoralis es un halcón de tamaño mediano conocido por su agilidad en vuelo y su habilidad para cazar presas pequeñas en hábitats forestales. Presenta un plumaje marrón oscuro que le proporciona camuflaje en su entorno natural.').
caracteristicas('Falco-Rufigularis', 'Animalia', 'Chordata', 'Marrón rojizo con manchas blancas y negras', '150-200 gramos', 'Pequeños mamíferos, aves e insectos', 'Bosques tropicales y zonas abiertas de América Central y del Sur', 'El Falco rufigularis es un halcón de tamaño mediano conocido por su garganta de color rojizo. Es un ave rapaz diurna que caza principalmente en vuelo, destacándose por su agilidad y velocidad.').
caracteristicas('Falco-Deiroleucus', 'Animalia', 'Chordata', 'Marrón rojizo con partes inferiores blancas y rayas oscuras', '150-200 gramos', 'Insectos y pequeños vertebrados', 'Bosques tropicales y áreas abiertas de América Central y del Sur', 'Pequeño halcón conocido por su agilidad en vuelo, con plumaje característico que le permite camuflarse en su entorno natural.').
caracteristicas('Falco-Peregrinus', 'Animalia', 'Chordata', 'Gris azulado en el dorso, blanco con manchas negras en el vientre', '900-1500 gramos', 'Aves y pequeños mamíferos', 'Zonas urbanas, acantilados y áreas abiertas en todo el mundo', 'El halcón peregrino es una ave rapaz conocida por su velocidad en vuelo, alcanzando hasta 320 km/h en picada. Es un depredador eficaz con una gran adaptabilidad a diferentes ambientes.').
caracteristicas('Touit-Costaricensis', 'Animalia', 'Chordata', 'Verde con tonos rojos y azulados', '80-100 gramos', 'Frutas y semillas', 'Bosques tropicales de Centroamérica', 'El Touit-Costaricensis es un loro pequeño y colorido, endémico de Costa Rica, conocido por su plumaje verde vibrante con manchas rojas y azuladas. Habita en áreas boscosas donde se alimenta principalmente de frutas y semillas, contribuyendo a la dispersión de plantas en su ecosistema.').
caracteristicas('Bolborhynchus-Lineola', 'Animalia', 'Chordata', 'Verde oliva con tonos amarillentos y manchas marrones', '60-80 gramos', 'Semillas, frutas, brotes y pequeños insectos', 'Bosques subtropicales y zonas arbustivas de América Central y del Sur', 'El Bolborhynchus lineola es un pequeño loro terrestre conocido por su plumaje predominantemente verde oliva con patrones moteados. Habita principalmente en regiones boscosas y es reconocido por su comportamiento tímido y dieta variada que incluye semillas y frutas.').
caracteristicas('Brotogeris-Jugularis', 'Animalia', 'Chordata', 'Verde con manchas amarillas y azuladas en las alas y la garganta', '40-60 gramos', 'Frutas, semillas, flores y néctar', 'Bosques tropicales, zonas abiertas y áreas urbanas en América Central', 'El Brotogeris jugularis, conocido como periquito de garganta gris, es un ave pequeña y vibrante que se distingue por su plumaje principalmente verde con detalles amarillos y azulados. Es muy social y se encuentra frecuentemente en grupos, adaptándose bien a diferentes hábitats desde bosques hasta áreas urbanas.').
caracteristicas('Pyrilia-Haematotis', 'Animalia', 'Chordata', 'verde, amarillo y rojo', 'aproximadamente 120 gramos', 'frutas, semillas e insectos', 'bosques tropicales y subtropicales', 'El Pyrilia haematotis es un loro de tamaño mediano conocido por su plumaje vibrante con tonos verdes, amarillos y rojos. Habita principalmente en selvas y áreas boscosas, donde se alimenta de frutas, semillas e insectos.').
caracteristicas('Pionus-Menstruus', 'Animalia', 'Chordata', 'Verde con manchas azules y rojo en la cola', '200-300 gramos', 'Frutas, semillas y nueces', 'Bosques tropicales y subtropicales de América Central y del Sur', 'El Pionus menstruus es un loro de tamaño mediano conocido por su plumaje verde con detalles azules y rojos. Es una especie sociable y ruidosa que habita principalmente en zonas boscosas.').
caracteristicas('Pionus-Senilis', 'Animalia', 'Chordata', 'Predominantemente verde con tonos azules y rojos en la cabeza', '200-300 gramos', 'Frutas, semillas, flores y algunos insectos', 'Bosques húmedos y áreas forestales de América Central', 'El Pionus Senilis es un loro de tamaño mediano conocido por su plumaje colorido y su comportamiento tranquilo. Es nativo de regiones montañosas y subtropicales, donde se alimenta principalmente de frutas y semillas.').
caracteristicas('Amazona-Autumnalis', 'Animalia', 'Chordata', 'Verde con tonos rojos y azules', '250-300 gramos', 'Frutas, semillas, nueces y vegetales', 'Bosques tropicales y subtropicales de América Central y del Sur', 'El Amazona autumnalis, conocido como cotorra de mejillas rojas, es un loro de tamaño mediano con plumaje principalmente verde, destacando sus mejillas rojas y algunas plumas azules en las alas. Es conocido por su capacidad para imitar sonidos y su comportamiento social.').
caracteristicas('Amazona-Auropalliata', 'Animalia', 'Chordata', 'Verde con manchas amarillas y rojas', '400-550 gramos', 'Frutas, semillas, nueces, flores', 'Bosques tropicales y subtropicales de América Central', 'La Amazona Auropalliata es un loro de tamaño mediano conocido por su plumaje predominantemente verde con distintivas manchas amarillas alrededor de los ojos y una franja roja en la frente. Es una especie social, ruidosa y muy inteligente, comúnmente encontrada en áreas de bosque húmedo y a menudo en parques y jardines.').
caracteristicas('Amazona-Ochrocephala', 'Animalia', 'Chordata', 'Verde con tonos amarillos y azulados en la cabeza', '300-400 gramos', 'Frutas, semillas, nueces y vegetación', 'Bosques tropicales y subtropicales de América Central y del Sur', 'Loro mediano conocido por su plumaje verde brillante y su capacidad para imitar sonidos. Habita en zonas boscosas y tiene una dieta variada basada en frutas y semillas.').
caracteristicas('Amazona-Albifrons', 'Animalia', 'Chordata', 'Verde con frente blanca y manchas rojas', '250-300 gramos', 'Frutas, semillas, flores y hojas', 'Bosques tropicales y subtropicales, áreas abiertas y manglares', 'La Amazona albifrons es un loro de tamaño mediano conocido por su frente blanca distintiva y su plumaje mayormente verde. Es una especie sociable que habita en regiones de Centroamérica y partes de México, donde se alimenta principalmente de frutas y semillas.').
caracteristicas('Amazona-Farinosa', 'Animalia', 'Chordata', 'Verde con tonos azulados y amarillos', '400-500 gramos', 'Frutas, semillas, nueces y flores', 'Selvas tropicales y áreas boscosas de América Central y del Sur', 'La Amazona farinosa es un loro de tamaño mediano conocido por su plumaje verde brillante con tonos azulados y amarillos, especialmente en la cabeza y las alas. Es una especie social y ruidosa, que habita principalmente en selvas tropicales donde se alimenta de una variedad de frutas y semillas.').
caracteristicas('Pyrrhura-Hoffmanni', 'Animalia', 'Chordata', 'Verde con tonos rojizos y azulados', '60-80 gramos', 'Semillas, frutas, flores y pequeños insectos', 'Bosques húmedos montanos de Costa Rica y Panamá', 'El Pyrrhura hoffmanni, conocido como periquito de Hoffmann, es un lorito pequeño y colorido, caracterizado por su plumaje verde con manchas rojas y azuladas. Es una especie social y activa que habita en bosques montanos y se alimenta principalmente de frutas y semillas.').
caracteristicas('Eupsittula-Nana', 'Animalia', 'Chordata', 'Verde con tonos amarillentos y azulados', '100-140 gramos', 'Frutas, semillas, flores y pequeños insectos', 'Áreas abiertas, sabanas, bordes de bosques y zonas semiáridas en América Central y del Sur', 'El Eupsittula nana, conocido comúnmente como perico enano o cotorra enana, es un pequeño loro que destaca por su tamaño compacto y su plumaje predominantemente verde con detalles amarillos y azules. Es una especie sociable y activa, que se alimenta principalmente de frutas y semillas, y habita en regiones semiáridas y abiertas.').
caracteristicas('Eupsittula-Canicularis', 'Animalia', 'Chordata', 'Verde con tonos amarillos y azulados', '120-140 gramos', 'Frutas, semillas, flores y pequeños insectos', 'Bosques tropicales y subtropicales, áreas abiertas con árboles', 'El eupsittula canicularis, conocido comúnmente como perico o cotorra aliamarilla, es un loro de tamaño mediano, caracterizado por su plumaje verde brillante con manchas amarillas en la cabeza y azul en las alas. Es una especie social y ruidosa, común en Centroamérica.').
caracteristicas('Eupsittula-Pertinax', 'Animalia', 'Chordata', 'Verde con tonos amarillos y azulados', '120-140 gramos', 'Frutas, semillas, flores y ocasionalmente insectos', 'Bosques tropicales, sabanas y áreas abiertas con árboles en América Central y del Sur', 'El Eupsittula pertinax, conocido comúnmente como cotorra, es un loro pequeño y colorido caracterizado por su plumaje verde brillante con detalles amarillos y azules. Es una especie sociable y ruidosa que se alimenta principalmente de frutas y semillas, y habita en diversas zonas forestales y abiertas.').
caracteristicas('Ara-Ambiguus', 'Animalia', 'Chordata', 'Verde, rojo y azul', '900 a 1100 gramos', 'Frutas, nueces, semillas y flores', 'Bosques tropicales húmedos de América Central y del Sur', 'El Ara ambiguus, conocido como guacamayo verde, es una especie de loro grande y colorido que habita principalmente en bosques lluviosos. Es reconocido por su plumaje vibrante y su capacidad para imitar sonidos. Está en peligro debido a la pérdida de hábitat y el comercio ilegal.').
caracteristicas('Ara-Macao', 'Animalia', 'Chordata', 'Rojo, azul y amarillo', '1 kg - 1.3 kg', 'Frutas, nueces, semillas, insectos', 'Selvas tropicales de América Central y del Sur', 'El Ara Macao es un loro grande y colorido conocido por su plumaje vibrante, su fuerte pico y su habilidad para imitar sonidos. Es una especie social y juega un papel importante en la dispersión de semillas en su ecosistema.').
caracteristicas('Psittacara-Finschi', 'Animalia', 'Chordata', 'Verde con tonos rojos y amarillos', '150-200 gramos', 'Frutas, semillas, nueces y vegetación', 'Bosques, áreas abiertas y zonas agrícolas en América Central y del Sur', 'El Psittacara finschi es un loro de tamaño mediano conocido por su plumaje principalmente verde con manchas rojas y amarillas. Es una especie social y ruidosa que habita en diversas áreas desde México hasta Perú, adaptándose bien a distintos ambientes.').
caracteristicas('Euchrepomis-Callinota', 'Animalia', 'Chordata', 'Predominantemente amarillo y negro con tonos marrones', 'Aproximadamente 20-25 gramos', 'Insectos y pequeños artrópodos', 'Bosques húmedos tropicales de América del Sur', 'Euchrepomis callinota es un ave pequeña y activa que se encuentra en los estratos intermedios de los bosques, reconocida por su plumaje brillante y su comportamiento insectívoro.').
caracteristicas('Cymbilaimus-Lineatus', 'Animalia', 'Chordata', 'Marrón y negro con patrones rayados', 'aproximadamente 100-120 gramos', 'Insectos y pequeños invertebrados', 'Bosques tropicales húmedos de América Central y del Sur', 'El Cymbilaimus lineatus, conocido como el gavilán rayado, es un ave de tamaño mediano con plumaje rayado que habita principalmente en el sotobosque de bosques tropicales húmedos. Se caracteriza por su comportamiento activo y su dieta basada en insectos.').
caracteristicas('Taraba-Major', 'Animalia', 'Chordata', 'Multicolor (predominantemente rojo, amarillo y verde)', 'Aproximadamente 250 gramos', 'Frutas, insectos y pequeños invertebrados', 'Bosques tropicales y subtropicales de América del Sur', 'El Taraba-Major es un ave de tamaño mediano conocida por su plumaje vibrante y su canto melodioso. Habita principalmente en las copas de los árboles donde se alimenta de frutas maduras e insectos, desempeñando un papel importante en la dispersión de semillas.').
caracteristicas('Thamnophilus-Doliatus', 'Animalia', 'Chordata', 'Negro y blanco con bandas', '20-25 gramos', 'Insectos y pequeños invertebrados', 'Bosques, selvas y áreas arbustivas de América Central y del Sur', 'El Thamnophilus doliatus es un ave paseriforme conocida como el hormiguero rayado, caracterizada por su plumaje rayado en blanco y negro y su comportamiento territorial.').
caracteristicas('Thamnophilus-Atrinucha', 'Animalia', 'Chordata', 'Negro y blanco', '30-40 gramos', 'Insectos y pequeños artrópodos', 'Bosques tropicales y subtropicales', 'El Thamnophilus atrinucha es un ave paseriforme conocida por su plumaje contrastante en negro y blanco, que habita en áreas boscosas donde se alimenta principalmente de insectos.').
caracteristicas('Thamnophilus-Bridgesi', 'Animalia', 'Chordata', 'Predominantemente negro con detalles blancos y grises', 'aproximadamente 30 gramos', 'Insectos y pequeños invertebrados', 'Bosques secos y áreas arbustivas en Ecuador y Perú', 'El Thamnophilus bridgesi es un ave paseriforme de la familia Thamnophilidae, conocida por su canto distintivo y su comportamiento territorial. Se caracteriza por su plumaje oscuro con contrastes claros, y su dieta se basa principalmente en insectos que captura en el sotobosque.').
caracteristicas('Thamnistes-Anabatinus', 'Animalia', 'Chordata', 'Marrón con patrones rayados y manchas blancas', '30-40 gramos', 'Insectos y pequeños invertebrados', 'Bosques húmedos tropicales y subtropicales de América Central y del Sur', 'El Thamnistes anabatinus es un ave pequeña y discreta conocida por su canto melodioso. Presenta un plumaje críptico que le permite camuflarse eficazmente entre la vegetación densa de su hábitat natural.').
caracteristicas('Dysithamnus-Mentalis', 'Animalia', 'Chordata', 'Predominantemente marrón oscuro con partes inferiores más claras', 'aproximadamente 15-20 gramos', 'Insectos y artrópodos', 'Bosques húmedos tropicales y subtropicales de América Central y del Sur', 'El Dysithamnus mentalis es un ave pequeña y discreta que habita en el sotobosque de bosques densos. Se caracteriza por su plumaje marrón oscuro y su comportamiento tímido, alimentándose principalmente de insectos que captura entre la vegetación baja.').
caracteristicas('Dysithamnus-Striaticeps', 'Animalia', 'Chordata', 'Marrón con rayas blancas y negras', 'aproximadamente 15-20 gramos', 'Insectos y otros artrópodos', 'Bosques húmedos tropicales y subtropicales de América Central', 'El Dysithamnus striaticeps es un ave pequeña de la familia Thamnophilidae, conocida por sus patrones estriados en la cabeza y su comportamiento insectívoro, habitando principalmente sotobosques densos.').
caracteristicas('Dysithamnus-Puncticeps', 'Animalia', 'Chordata', 'Marrón con manchas claras', '15-20 gramos', 'Insectos y otros artrópodos', 'Bosques húmedos tropicales y subtropicales', 'El Dysithamnus puncticeps es un ave pequeña de la familia Thamnophilidae, conocida por su patrón moteado en la cabeza y su comportamiento insectívoro en el sotobosque.').
caracteristicas('Epinecrophylla-Fulviventris', 'Animalia', 'Chordata', 'Marrón y crema con tonos fulvos', '10-12 gramos', 'Insectos y pequeños artrópodos', 'Bosques húmedos tropicales de América Central y del Sur', 'El Epinecrophylla fulviventris es un pequeño pájaro insectívoro conocido por su plumaje marrón y crema con tonos fulvos en la región ventral. Habita principalmente en bosques densos y húmedos, donde se alimenta de insectos que captura entre la vegetación.').
caracteristicas('Myrmotherula-Axillaris', 'Animalia', 'Chordata', 'Predominantemente gris con zonas blancas y negras', 'aproximadamente 7-10 gramos', 'Insectos y pequeños artrópodos', 'Bosques tropicales y subtropicales, principalmente en la región amazónica', 'Pequeña ave paseriforme de la familia Thamnophilidae, conocida por su comportamiento activo y su hábitat en el sotobosque de selvas húmedas.').
caracteristicas('Myrmotherula-Schisticolor', 'Animalia', 'Chordata', 'verde oliva, con partes inferiores amarillentas y rayas blancas en la cabeza', 'aproximadamente 8-10 gramos', 'insectos y otros pequeños invertebrados', 'bosques húmedos tropicales y subtropicales de América Central y del Sur', 'El Myrmotherula schisticolor es un pequeño pájaro insectívoro conocido como el tirano de vientre oliváceo, caracterizado por su plumaje discreto y su comportamiento activo en la búsqueda de alimento en el sotobosque.').
caracteristicas('Microrhopias-Quixensis', 'Animalia', 'Chordata', 'Verde con tonos amarillos y marrones', '15-20 gramos', 'Insectos y pequeños invertebrados', 'Bosques húmedos tropicales en América Central', 'El Microrhopias quixensis es un pequeño ave paseriforme conocido por su plumaje verde brillante y su comportamiento activo, común en áreas boscosas donde se alimenta principalmente de insectos.').
caracteristicas('Cercomacroides-Tyrannina', 'Animalia', 'Chordata', 'Predominantemente marrón con tonos grisáceos', 'Aproximadamente 15-20 gramos', 'Insectos y pequeños artrópodos', 'Bosques tropicales húmedos de América del Sur', 'Cercomacroides tyrannina es un ave paseriforme de la familia Thamnophilidae, conocida por su comportamiento territorial y su canto distintivo. Se encuentra principalmente en áreas boscosas densas donde se alimenta activamente de insectos.').
caracteristicas('Gymnocichla-Nudiceps', 'Animalia', 'Chordata', 'negro con cabeza blanca', 'aproximadamente 150 gramos', 'insectos y pequeños invertebrados', 'bosques tropicales y áreas de densa vegetación', 'El Gymnocichla nudiceps es un ave paseriforme conocida por su distintiva cabeza blanca y cuerpo negro, que habita principalmente en regiones tropicales, donde se alimenta de insectos capturados en vuelo o en el follaje.').
caracteristicas('Poliocrania-Exsul', 'Animalia', 'Chordata', 'Verde oliva con manchas marrones', '1.2 kg', 'Insectos y pequeños frutos', 'Bosques tropicales húmedos', 'Ave pequeña y sigilosa, conocida por su plumaje camuflado y su habilidad para moverse entre la densa vegetación.').
caracteristicas('Sipia-Laemosticta', 'Animalia', 'Chordata', 'Marrón con manchas blancas y negras', '20-25 gramos', 'Insectos y pequeños invertebrados', 'Bosques húmedos y áreas montañosas de América Central', 'El Sipia-Laemosticta es un pequeño ave paseriforme conocido por sus patrones moteados que le permiten camuflarse en el sotobosque. Es principalmente insectívoro y activo durante el día.').
caracteristicas('Hafferia-Zeledoni', 'Animalia', 'Chordata', 'Verde esmeralda con reflejos azulados y partes inferiores blancas', 'aproximadamente 5 gramos', 'Néctar, insectos pequeños', 'Bosques húmedos y áreas montañosas de América Central', 'Pequeño colibrí caracterizado por su vibrante plumaje verde y su comportamiento ágil al alimentarse de flores y capturar insectos.').
